#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CommandSpec {
    pub name: String,
    pub description: String,
}

/// Built-in command metadata. Plugin commands can be appended later; the TUI
/// menu, `/help`, and parsing should share this registry rather than keeping a
/// second command table.
#[derive(Debug, Clone, Default)]
pub struct CommandRegistry {
    entries: Vec<CommandSpec>,
}

impl CommandRegistry {
    pub fn builtin() -> Self {
        Self {
            entries: COMMANDS
                .iter()
                .map(|(name, description)| CommandSpec {
                    name: (*name).to_string(),
                    description: (*description).to_string(),
                })
                .collect(),
        }
    }

    pub fn all(&self) -> &[CommandSpec] {
        &self.entries
    }

    /// Append embedder commands without duplicating a built-in name.
    pub fn extend(&mut self, entries: impl IntoIterator<Item = (String, String)>) {
        for (name, description) in entries {
            let name = if name.starts_with('/') {
                name
            } else {
                format!("/{name}")
            };
            if self.entries.iter().any(|entry| entry.name == name) {
                continue;
            }
            self.entries.push(CommandSpec { name, description });
        }
    }

    pub fn candidates(&self, prefix: &str) -> Vec<&CommandSpec> {
        self.entries
            .iter()
            .filter(|spec| spec.name.starts_with(prefix))
            .collect()
    }
}

