//! Small terminal theme used by the linear TUI and approval pager.
//!
//! Styling is intentionally dependency-free: ANSI SGR codes only, disabled for
//! non-TTY output, `NO_COLOR`, `CLICOLOR=0`, and `TERM=dumb`.

use std::fmt::Display;
use std::io::IsTerminal;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Theme {
    ansi: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tone {
    Accent,
    Bright,
    Success,
    Danger,
    Warning,
    Muted,
    Magenta,
}

pub const PROMPT: &str = "▸";
pub const ASSISTANT: &str = "◆";
pub const THINKING: &str = "◇";
pub const TOOL: &str = "»";
pub const OK: &str = "✓";
pub const ERR: &str = "✗";
pub const WARN: &str = "!";
pub const COMPACT: &str = "⇣";
pub const TURN: &str = "╰─";
pub const BRANCH: &str = "│";

impl Theme {
    pub fn detect_stdout() -> Self {
        Self::from_tty(std::io::stdout().is_terminal())
    }

    pub fn detect_stderr() -> Self {
        Self::from_tty(std::io::stderr().is_terminal())
    }

    pub fn from_tty(tty: bool) -> Self {
        let no_color = std::env::var_os("NO_COLOR").is_some();
        let dumb = std::env::var("TERM").is_ok_and(|term| term == "dumb");
        let clicolor_off = std::env::var("CLICOLOR").is_ok_and(|value| value == "0");
        Self {
            ansi: tty && !no_color && !dumb && !clicolor_off,
        }
    }

    pub fn plain() -> Self {
        Self { ansi: false }
    }

    #[cfg(test)]
    fn ansi_forced() -> Self {
        Self { ansi: true }
    }

    pub fn is_ansi(self) -> bool {
        self.ansi
    }

    pub fn paint(self, tone: Tone, text: impl Display) -> String {
        if !self.ansi {
            return text.to_string();
        }
        let code = match tone {
            Tone::Accent => "1;36",
            Tone::Bright => "1;37",
            Tone::Success => "1;32",
            Tone::Danger => "1;31",
            Tone::Warning => "1;33",
            Tone::Muted => "2",
            Tone::Magenta => "1;35",
        };
        format!("\x1b[{code}m{text}\x1b[0m")
    }

    /// Build spans only after sanitization; model-provided ANSI is never trusted.
    pub fn row(self, text: &str, code: bool) -> ratatui::text::Line<'static> {
        use ratatui::{
            style::{Color, Modifier, Style},
            text::Span,
        };
        let text = crate::text_layout::clean_text(text);
        let style = |tone: Tone| {
            if !self.ansi {
                return Style::default();
            }
            match tone {
                Tone::Accent => Style::default()
                    .fg(Color::Cyan)
                    .add_modifier(Modifier::BOLD),
                Tone::Bright => Style::default().add_modifier(Modifier::BOLD),
                Tone::Success => Style::default().fg(Color::Green),
                Tone::Danger => Style::default().fg(Color::Red),
                Tone::Warning => Style::default().fg(Color::Yellow),
                Tone::Muted => Style::default().add_modifier(Modifier::DIM),
                Tone::Magenta => Style::default().fg(Color::Magenta),
            }
        };
        if !code {
            if let Some((level, heading)) = crate::markdown::heading_with_level(&text) {
                let mut heading_style = style(Tone::Accent);
                if self.ansi {
                    if level == 1 {
                        heading_style = heading_style.add_modifier(Modifier::UNDERLINED);
                    } else if level >= 3 {
                        heading_style = heading_style
                            .fg(Color::Cyan)
                            .remove_modifier(Modifier::BOLD);
                    }
                }
                return vec![Span::styled(heading, heading_style)].into();
            }
        }
        let (text, block_style) = if code {
            (text, None)
        } else if let Some(block) = crate::markdown::block(&text) {
            let tone = match block.kind {
                crate::markdown::BlockKind::Quote => Some(Tone::Muted),
                crate::markdown::BlockKind::Task(true) => Some(Tone::Success),
                crate::markdown::BlockKind::Rule => Some(Tone::Muted),
                _ => None,
            };
            (block.text, tone)
        } else {
            (text, None)
        };
        let trimmed = text.trim_start();
        let tone = if trimmed.contains("│ - ")
            || trimmed.starts_with("✗")
            || trimmed.starts_with('-') && !trimmed.starts_with("- ")
        {
            Some(Tone::Danger)
        } else if trimmed.contains("│ + ") || trimmed.starts_with("✓") || trimmed.starts_with('+')
        {
            Some(Tone::Success)
        } else if trimmed.starts_with('!') {
            Some(Tone::Warning)
        } else if trimmed.starts_with('#')
            || trimmed.starts_with("@@")
            || trimmed.starts_with('▎')
            || trimmed.starts_with('→')
        {
            Some(Tone::Accent)
        } else if trimmed.starts_with("```") {
            Some(Tone::Muted)
        } else {
            None
        };
        if let Some(tone) = tone {
            return vec![Span::styled(text, style(tone))].into();
        }
        if let Some((prefix, rest)) = text.split_once('▸') {
            return vec![
                Span::styled(format!("{prefix}▸"), style(Tone::Accent)),
                Span::raw(rest.to_owned()),
            ]
            .into();
        }
        if code {
            return self.code_tokens(&crate::syntax::highlight(&text));
        }
        let base = block_style.map_or(Style::default(), style);
        let spans: Vec<_> = crate::markdown::inline(&text)
            .into_iter()
            .map(|span| {
                let mut style = base;
                if !self.ansi {
                    return Span::styled(span.text, style);
                }
                if span.style.bold {
                    style = style.add_modifier(Modifier::BOLD);
                }
                if span.style.italic {
                    style = style.add_modifier(Modifier::ITALIC);
                }
                if span.style.strike {
                    style = style.add_modifier(Modifier::CROSSED_OUT);
                }
                if span.style.code {
                    style = style.fg(Color::Cyan);
                }
                if span.style.link {
                    style = style.fg(Color::Cyan).add_modifier(Modifier::UNDERLINED);
                }
                if span.style.math {
                    style = style.fg(Color::Magenta).add_modifier(Modifier::ITALIC);
                }
                Span::styled(span.text, style)
            })
            .collect();
        spans.into()
    }

//! Width-aware rendering for structured change previews.
//!
//! This module is pure: it turns a `ChangePreview` into terminal rows. The
//! approval pager and the headless fallback both render those rows, so layout
//! and line-number alignment are tested without a terminal.

use crate::text_layout::{clean_text, wrap};
use niucode_tools::{ChangePreview, FilePreview, LineKind, PreviewBody, PreviewLine};
use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

const MIN_WIDTH: usize = 40;
const MIN_BODY_WIDTH: usize = 4;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RowKind {
    File,
    Hunk,
    Context,
    Add,
    Remove,
    Note,
    Warning,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Row {
    pub kind: RowKind,
    pub text: String,
}

pub fn layout(preview: &ChangePreview, width: usize) -> Vec<Row> {
    let width = width.max(MIN_WIDTH);
    let mut rows = Vec::new();

    if let Some(warning) = &preview.warning {
        rows.extend(wrap_prefixed("! ", warning, width, RowKind::Warning));
    }

    match &preview.body {
        PreviewBody::Diff { files } => {
            for file in files {
                rows.extend(file_rows(file, width));
            }
        }
        PreviewBody::Command { command } => {
            if command.is_empty() {
                rows.push(note("(empty command)"));
            } else {
                for (index, line) in command.lines().enumerate() {
                    let prefix = if index == 0 { "$ " } else { "  " };
                    rows.extend(wrap_prefixed(prefix, line, width, RowKind::Note));
                }
            }
        }
        PreviewBody::Note { message } => {
            rows.extend(wrap_prefixed("! ", message, width, RowKind::Note));
        }
    }

    if rows.is_empty() {
        rows.push(note("(nothing to preview)"));
    }
    rows
}

/// Render a preview without color, for headless approval and non-TTY input.
pub fn render_plain(preview: &ChangePreview, width: usize) -> String {
    let mut rendered = String::new();
    for row in layout(preview, width) {
        rendered.push_str(&row.text);
        rendered.push('\n');
    }
    rendered
}

/// Starting row of each file header, in display order.
pub fn file_starts(rows: &[Row]) -> Vec<usize> {
    rows.iter()
        .enumerate()
        .filter_map(|(index, row)| (row.kind == RowKind::File).then_some(index))
        .collect()
}

pub fn display_width(text: &str) -> usize {
    text.width()
}

fn file_rows(file: &FilePreview, width: usize) -> Vec<Row> {
    let stats = format!("+{} -{}", file.added, file.removed);
    let path = clean_text(&file.path);
    let label = if file.is_new {
        format!("{path} (new file)")
    } else {
        path
    };
    let label_budget = width
        .saturating_sub(2 + display_width(&stats) + 2)
        .max(MIN_BODY_WIDTH);
    let label = fit_tail(&label, label_budget);
    let padding = width.saturating_sub(2 + display_width(&label) + display_width(&stats));
    let header = format!("▎ {label}{}{stats}", " ".repeat(padding));

    let mut rows = vec![Row {
        kind: RowKind::File,
        text: header,
    }];

    if file.hunks.is_empty() {
        rows.push(Row {
            kind: RowKind::Note,
            text: "  (no textual changes)".to_string(),
        });
        return rows;
    }

    let (old_width, new_width) = line_number_widths(file);
    for hunk in &file.hunks {
        rows.push(Row {
            kind: RowKind::Hunk,
            text: format!(
                "@@ -{} +{} @@",
                range_text(hunk.old_start, hunk.old_len),
                range_text(hunk.new_start, hunk.new_len)
            ),
        });
        for line in &hunk.lines {
            rows.extend(render_line(line, old_width, new_width, width));
        }
    }

    rows
}

fn render_line(line: &PreviewLine, old_width: usize, new_width: usize, width: usize) -> Vec<Row> {
    let sign = match line.kind {
        LineKind::Context => ' ',
        LineKind::Add => '+',
        LineKind::Remove => '-',
    };
    let old = line
        .old_line
        .map(|line| line.to_string())
        .unwrap_or_default();
    let new = line
        .new_line
        .map(|line| line.to_string())
        .unwrap_or_default();
    let prefix = format!(
        "{old:>old_width$} {new:>new_width$} │ {sign} ",
        old_width = old_width,
        new_width = new_width
    );
    let continuation = format!(
        "{:>old_width$} {:>new_width$} │   ",
        "",
        "",
        old_width = old_width,
        new_width = new_width
    );
    let body_width = width
        .saturating_sub(display_width(&prefix))
        .max(MIN_BODY_WIDTH);
    let cleaned = clean_text(&line.text);
    let segments = wrap(&cleaned, body_width);
    let kind = match line.kind {
        LineKind::Context => RowKind::Context,
        LineKind::Add => RowKind::Add,
        LineKind::Remove => RowKind::Remove,
    };

    segments
        .into_iter()
        .enumerate()
        .map(|(index, segment)| Row {
            kind,
            text: if index == 0 {
                format!("{prefix}{segment}")
            } else {
                format!("{continuation}{segment}")
            },
        })
        .collect()
}

fn line_number_widths(file: &FilePreview) -> (usize, usize) {
    let max_old = file
        .hunks
        .iter()
        .flat_map(|hunk| &hunk.lines)
        .filter_map(|line| line.old_line)
        .max()
        .unwrap_or(0);
    let max_new = file
        .hunks
        .iter()
        .flat_map(|hunk| &hunk.lines)
        .filter_map(|line| line.new_line)
        .max()
        .unwrap_or(0);

//! Full-screen approval pager for structured diffs.
//!
//! This is an overlay for approval only; the session itself stays linear. The
//! pager owns no session state and disappears after a decision.

use std::io::{self, Write};

use crate::text_layout::{clean_text, clip};
use crossterm::cursor::{Hide, MoveTo, Show};
use crossterm::event::{self, Event, KeyCode, KeyEventKind, KeyModifiers};
use crossterm::queue;
use crossterm::style::{Attribute, Print, ResetColor, SetAttribute};
use crossterm::terminal::{self, Clear, ClearType, EnterAlternateScreen, LeaveAlternateScreen};
use niucode_agent::ApprovalRequest;
use niucode_tools::ChangePreview;
use unicode_width::UnicodeWidthStr;

use crate::diff::{self, file_starts, Row, RowKind};
use crate::theme::{Theme, Tone};
use crate::ApprovalKeys;

const MIN_WIDTH: usize = 40;
const MIN_HEIGHT: usize = 6;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ApprovalChoice {
    Allow,
    Deny,
    Session,
}

/// Map a key press to an approval choice using the configured keys.
pub(crate) fn choice_for_key(code: KeyCode, keys: ApprovalKeys) -> Option<ApprovalChoice> {
    match code {
        KeyCode::Char(character) if character.eq_ignore_ascii_case(&keys.allow) => {
            Some(ApprovalChoice::Allow)
        }
        KeyCode::Char(character) if character.eq_ignore_ascii_case(&keys.deny) => {
            Some(ApprovalChoice::Deny)
        }
        KeyCode::Char(character) if character.eq_ignore_ascii_case(&keys.session) => {
            Some(ApprovalChoice::Session)
        }
        _ => None,
    }
}

/// Show a width-aware diff pager and return the user's decision.
///
/// `Ok(None)` means the terminal is too small, so the caller should fall back
/// to a plain preview and the line-based prompt.
pub fn review_diff(
    request: &ApprovalRequest,
    preview: &ChangePreview,
    theme: Theme,
    keys: ApprovalKeys,
) -> io::Result<Option<ApprovalChoice>> {
    let (columns, rows) = terminal::size()?;
    let width = columns.saturating_sub(1) as usize;
    let height = rows as usize;
    if width < MIN_WIDTH || height < MIN_HEIGHT {
        return Ok(None);
    }

    let _guard = ScreenGuard::enter()?;
    let mut state = ReviewState::new(request, preview, width, height, theme, keys);
    let mut out = io::stdout();

    loop {
        state.draw(&mut out)?;
        match event::read()? {
            Event::Key(key) if key.kind == KeyEventKind::Press => {
                if let Some(choice) = choice_for_key(key.code, keys) {
                    return Ok(Some(choice));
                }
                match key.code {
                    KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('Q') => {
                        return Ok(Some(ApprovalChoice::Deny));
                    }
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        return Ok(Some(ApprovalChoice::Deny));
                    }
                    KeyCode::Char('j') | KeyCode::Down => state.scroll_by(1),
                    KeyCode::Char('k') | KeyCode::Up => state.scroll_by(-1),
                    KeyCode::PageDown | KeyCode::Char(' ') => {
                        state.scroll_by(state.body_height() as isize)
                    }
                    KeyCode::PageUp | KeyCode::Char('b') => {
                        state.scroll_by(-(state.body_height() as isize))
                    }
                    KeyCode::Char('g') | KeyCode::Home => state.scroll = 0,
                    KeyCode::Char('G') | KeyCode::End => state.scroll = state.max_scroll(),
                    KeyCode::Char('n') | KeyCode::Char(']') => state.jump_file(1),
                    KeyCode::Char('p') | KeyCode::Char('[') => state.jump_file(-1),
                    _ => {}
                }
            }
            Event::Resize(columns, rows) => {
                let width = columns.saturating_sub(1) as usize;
                let height = rows as usize;
                if width < MIN_WIDTH || height < MIN_HEIGHT {
                    return Ok(None);
                }
                state.relayout(width, height);
            }
            _ => {}
        }
    }
}

struct ReviewState<'a> {
    request: &'a ApprovalRequest,
    preview: &'a ChangePreview,
    rows: Vec<Row>,
    file_starts: Vec<usize>,
    width: usize,
    height: usize,
    scroll: usize,
    theme: Theme,
    keys: ApprovalKeys,
}

impl<'a> ReviewState<'a> {
    fn new(
        request: &'a ApprovalRequest,
        preview: &'a ChangePreview,
        width: usize,
        height: usize,
        theme: Theme,
        keys: ApprovalKeys,
    ) -> Self {
        let rows = diff::layout(preview, width);
        let file_starts = file_starts(&rows);
        Self {
            request,
            preview,
            rows,
            file_starts,
            width,
            height,
            scroll: 0,
            theme,
            keys,
        }
    }

    fn body_height(&self) -> usize {
        self.height.saturating_sub(2)
    }

    fn max_scroll(&self) -> usize {
        self.rows.len().saturating_sub(self.body_height())
    }

    fn clamp(&mut self) {
        self.scroll = self.scroll.min(self.max_scroll());
    }

    fn scroll_by(&mut self, delta: isize) {
        let target = self.scroll as isize + delta;
        self.scroll = target.clamp(0, self.max_scroll() as isize) as usize;
    }

    fn current_file(&self) -> Option<usize> {
        self.file_starts
            .iter()
            .rposition(|start| *start <= self.scroll)
    }

    fn jump_file(&mut self, delta: isize) {
        if self.file_starts.is_empty() {
            return;
        }
        let next = match self.current_file() {
            Some(current) => {
                (current as isize + delta).rem_euclid(self.file_starts.len() as isize) as usize
            }
            None if delta >= 0 => 0,
            None => self.file_starts.len() - 1,
        };
        self.scroll = self.file_starts[next];
    }

    fn relayout(&mut self, width: usize, height: usize) {
        let anchor = self.scroll;
        self.width = width;
        self.height = height;
        self.rows = diff::layout(self.preview, width);
        self.file_starts = file_starts(&self.rows);
        self.scroll = anchor.min(self.max_scroll());
    }

    fn draw(&mut self, out: &mut impl Write) -> io::Result<()> {
        self.clamp();
        let width = self.width;

        queue!(out, MoveTo(0, 0), Clear(ClearType::CurrentLine))?;
        if self.theme.is_ansi() {
            queue!(out, SetAttribute(Attribute::Reverse))?;
        }

//! One editor state for linear and inline presentations, idle and running tasks.
use crate::{
