const MAX_TASKS: usize = 4;
const MAX_STEPS: usize = 12;
const MAX_TIMEOUT_SECS: u64 = 600;
const MAX_PROMPT_CHARS: usize = 8_000;
const MAX_SUMMARY_CHARS: usize = 2_000;
