//! In-process control plane. The loop and control messages share one log writer.
use crate::{AgentConfig, AgentEvent, ApprovalRequest, RunOutcome};
use anyhow::Result;
use niucode_core::{load, now_ms, Event, SessionLog};
use niucode_provider::{ChatMessage, Provider};
use std::collections::{HashMap, VecDeque};
use std::future::Future;
use tokio::sync::{mpsc, watch};

const QUEUE_CAPACITY: usize = 32;
const MAX_MESSAGE_BYTES: usize = 65_536;

#[derive(Debug, Clone)]
pub enum RuntimeCommand {
    Submit {
        id: String,
        text: String,
        queued: bool,
    },
    Approve {
        request_id: String,
        allowed: bool,
    },
}
#[derive(Debug, Clone)]
pub enum RuntimeEvent {
    Agent(AgentEvent),
    Input {
        id: String,
        queued: bool,
        applied: bool,
    },
    Approval {
        request_id: String,
        call_id: String,
        request: ApprovalRequest,
    },
    TaskDone {
        id: String,
        outcome: RunOutcome,
    },
    InputRejected {
        id: String,
        reason: String,
    },
    Notice(String),
}

pub struct RuntimeClient {
    pub commands: mpsc::Sender<RuntimeCommand>,
    pub events: mpsc::Receiver<RuntimeEvent>,
    cancel: watch::Sender<bool>,
}
impl RuntimeClient {
    pub fn cancel(&self) {
        let _ = self.cancel.send(true);
    }
}
pub struct RuntimeEndpoint {
    commands: mpsc::Receiver<RuntimeCommand>,
    events: mpsc::Sender<RuntimeEvent>,
    cancel: watch::Receiver<bool>,
}
pub fn runtime_channel() -> (RuntimeClient, RuntimeEndpoint) {
    let (commands, receiver) = mpsc::channel(QUEUE_CAPACITY);
    let (sender, events) = mpsc::channel(64);
    let (cancel, cancelled) = watch::channel(false);
    (
        RuntimeClient {
            commands,
            events,
            cancel,
        },
        RuntimeEndpoint {
            commands: receiver,
            events: sender,
            cancel: cancelled,
        },
    )
}

#[derive(Debug)]
pub struct Cancelled;
impl std::fmt::Display for Cancelled {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("task cancelled; completed changes are preserved")
    }
}
impl std::error::Error for Cancelled {}

#[derive(Debug, Clone)]
pub struct PendingInput {
    pub id: String,
    pub text: String,
    pub queued: bool,
}
/// Central projection used by the runtime and by clients displaying a resumed queue.
pub fn pending_inputs(events: &[Event]) -> Vec<PendingInput> {
    let mut pending = Vec::new();
    for event in events {
        match event {
            Event::InputSubmitted {
                id, text, queued, ..
            } => {
                if !pending.iter().any(|m: &PendingInput| &m.id == id) {
                    pending.push(PendingInput {
                        id: id.clone(),
                        text: text.clone(),
                        queued: *queued,
                    });
                }
            }
            Event::InputApplied { id, .. } => pending.retain(|m| &m.id != id),
            _ => {}
        }
    }
    pending
}

enum Transport<'a> {
    Callbacks {
        approver: &'a mut dyn FnMut(&ApprovalRequest) -> bool,
        observer: &'a mut dyn FnMut(AgentEvent),
    },
    Connected(RuntimeEndpoint),
}
pub(crate) struct RunIo<'a> {
    transport: Transport<'a>,
    pending: VecDeque<PendingInput>,
    seen: HashMap<String, (String, bool)>,
    pub(crate) starting: Option<PendingInput>,
}
impl<'a> RunIo<'a> {
    pub(crate) fn callbacks(
        approver: &'a mut dyn FnMut(&ApprovalRequest) -> bool,
        observer: &'a mut dyn FnMut(AgentEvent),
    ) -> Self {
        Self {
            transport: Transport::Callbacks { approver, observer },
            pending: VecDeque::new(),
            seen: HashMap::new(),
            starting: None,
        }
    }
    fn connected(endpoint: RuntimeEndpoint, session: &SessionLog) -> Result<Self> {
        let events = load(session.path())?.events;
        let pending = pending_inputs(&events).into();
        let seen = events
            .iter()
            .filter_map(|e| match e {
                Event::InputSubmitted {
                    id, text, queued, ..
                } => Some((id.clone(), (text.clone(), *queued))),
                _ => None,
            })
            .collect();
        Ok(Self {
            transport: Transport::Connected(endpoint),
            pending,
            seen,
            starting: None,
        })
    }
    async fn emit(&mut self, event: RuntimeEvent) -> Result<()> {
        match &mut self.transport {
            Transport::Callbacks { observer, .. } => {
                if let RuntimeEvent::Agent(event) = event {
                    observer(event);
                }
            }
            Transport::Connected(endpoint) => {
                if *endpoint.cancel.borrow() {
                    return Err(Cancelled.into());
                }
                tokio::select! {
                    biased;
                    _ = endpoint.cancel.changed() => return Err(Cancelled.into()),
                    result = endpoint.events.send(event) => result.map_err(|_| Cancelled)?,
                }
            }
        }
        Ok(())
    }
    pub(crate) async fn observe(&mut self, event: AgentEvent) -> Result<()> {
        self.emit(RuntimeEvent::Agent(event)).await
    }
    async fn accept(&mut self, session: &SessionLog, command: RuntimeCommand) -> Result<()> {
        let RuntimeCommand::Submit { id, text, queued } = command else {
            return self
                .emit(RuntimeEvent::Notice("stale approval ignored".into()))
                .await;
        };
        if let Some(previous) = self.seen.get(&id) {
            if previous != &(text, queued) {
                return self
                    .emit(RuntimeEvent::InputRejected {
                        id,
                        reason: "ID already used for different content".into(),
                    })
                    .await;

//! Bounded workspace evidence. Baselines are session events, never a side store.
use niucode_core::{Event, FileSnapshot, ProcessOutcome, WorkspaceSnapshot};
use niucode_tools::digest;
use similar::TextDiff;
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Component, Path, PathBuf};
use std::process::Stdio;
use std::time::{Duration, Instant};
use tokio::io::AsyncReadExt;

const MAX_FILES: usize = 2000;
const MAX_FILE: u64 = 512 * 1024;
const MAX_BYTES: usize = 4 * 1024 * 1024;

/// The deadline covers enumeration and reads. Per-file metadata is checked
/// before/after reading; a live workspace snapshot is not a transaction.
pub(crate) async fn capture(root: &Path, session_path: &Path, text: bool) -> WorkspaceSnapshot {
    let started = Instant::now();
    let mut snapshot = WorkspaceSnapshot {
        complete: true,
        files: Vec::new(),
        notes: Vec::new(),
    };
    let root = match tokio::fs::canonicalize(root).await {
        Ok(root) => root,
        Err(error) => {
            snapshot.complete = false;
            snapshot
                .notes
                .push(format!("workspace unavailable: {error}"));
            return snapshot;
        }
    };
    let root = root.as_path();
    let artifact_directory = session_path
        .ancestors()
        .find(|p| p.extension().is_some_and(|ext| ext == "subagents"))
        .map(Path::to_path_buf)
        .unwrap_or_else(|| session_path.with_extension("subagents"));
    let parent_log = artifact_directory.with_extension("jsonl");
    let paths = match tokio::time::timeout(Duration::from_secs(1), git_paths(root)).await {
        Ok(Some(paths)) => paths,
        _ => {
            snapshot.complete = false;
            snapshot
                .notes
                .push("Git enumeration unavailable; bounded non-ignored file coverage only".into());
            let mut paths = Vec::new();
            let walker = ignore::WalkBuilder::new(root)
                .hidden(false)
                .require_git(false)
                .follow_links(false)
                .filter_entry(|e| {
                    !matches!(
                        e.file_name().to_str(),
                        Some(".git" | "target" | "node_modules" | ".niucode")
                    )
                })
                .build();
            for entry in walker {
                tokio::task::yield_now().await;
                if paths.len() >= MAX_FILES || started.elapsed() > Duration::from_secs(2) {
                    break;
                }
                if let Ok(e) = entry {
                    if e.file_type().is_some_and(|t| t.is_file() || t.is_symlink()) {
                        if let Ok(path) = e.path().strip_prefix(root) {
                            paths.push(path.to_path_buf());
                        }
                    }
                }
            }
            paths
        }
    };
    let mut bytes = 0;
    for path in paths {
        tokio::task::yield_now().await;
        if snapshot.files.len() >= MAX_FILES
            || bytes >= MAX_BYTES
            || started.elapsed() > Duration::from_secs(2)
        {
            snapshot.complete = false;
            snapshot
                .notes
                .push("workspace evidence budget reached (2000 files / 4 MiB / 2s)".into());
            break;
        }
        if path.is_absolute()
            || path
                .components()
                .any(|c| !matches!(c, Component::Normal(_) | Component::CurDir))
        {
            snapshot.complete = false;
            continue;
        }
        let absolute = root.join(&path);
        if absolute == session_path
            || absolute == parent_log
            || absolute.starts_with(&artifact_directory)
        {
            continue;
        }
        let Some(name) = path.to_str() else {
            snapshot.complete = false;
            snapshot
                .notes
                .push("non-UTF-8 path omitted from review".into());
            continue;
        };
        let name = name.replace('\\', "/");
        if path
            .file_name()
            .and_then(|n| n.to_str())
            .is_some_and(|n| n.starts_with(".env"))
        {
            snapshot.complete = false;
            snapshot.notes.push(format!(
                "{name}: environment file excluded from content capture"
            ));
            continue;
        }
        let metadata = match tokio::fs::symlink_metadata(&absolute).await {
            Ok(m) => m,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => continue,
            Err(e) => {
                snapshot.complete = false;
                snapshot.notes.push(format!("{name}: {e}"));
                continue;
            }
        };
        if !metadata.is_file()
            || metadata.len() > MAX_FILE
            || bytes + metadata.len() as usize > MAX_BYTES
        {
            snapshot.complete = false;
            snapshot.files.push(FileSnapshot {
                path: name,
                digest: None,
                text: None,
                mode: None,
                note: Some("symlink/non-file or content budget; not fully covered".into()),
            });
            continue;
        }
        // Never follow a tracked symlink or symlinked parent outside the workspace.
        let canonical = match tokio::fs::canonicalize(&absolute).await {
            Ok(p) if p.starts_with(root) => p,
            _ => {
                snapshot.complete = false;
                snapshot
                    .notes
                    .push(format!("{name}: path resolution changed/outside workspace"));
                continue;
            }
        };
        let content =
            match tokio::time::timeout(Duration::from_millis(200), tokio::fs::read(&canonical))
                .await
            {
                Ok(Ok(content)) => content,
                _ => {
                    snapshot.complete = false;
                    snapshot.notes.push(format!("{name}: content unavailable"));
                    continue;
                }
            };
        bytes += content.len();
        let after = tokio::fs::metadata(&absolute).await.ok();
        let stable = after
            .as_ref()
            .is_some_and(|after| same_metadata(&metadata, after))
            && content.len() as u64 == metadata.len();
        #[cfg(unix)]
        let mode = {
            use std::os::unix::fs::MetadataExt;
            Some(metadata.mode())
        };
        #[cfg(not(unix))]
        let mode = None;
        let (hash, body, note) = if stable {
            let hash = Some(digest(&content));
            match String::from_utf8(content) {
                Ok(body) => (hash, text.then_some(body), None),
                Err(_) => (hash, None, Some("binary content: digest only".into())),
            }
        } else {
            snapshot.complete = false;
            (None, None, Some("file changed during capture".into()))
        };
        snapshot.files.push(FileSnapshot {
            path: name,
            digest: hash,
            text: body,
            mode,
            note,
        });
    }
    snapshot.files.sort_by(|a, b| a.path.cmp(&b.path));
    snapshot

//! Context projection, token estimation, and deterministic compaction.
//!
//! The event log is the truth. A projection is a lossy model context built from
//! that log; compaction appends a new event and never rewrites history.

use std::collections::{BTreeSet, HashMap};

use anyhow::{bail, Result};
use niucode_core::{Event, ToolCall};
use niucode_provider::{ChatMessage, ToolSpec};

pub const DEFAULT_CONTEXT_BUDGET: usize = 64_000;
pub const DEFAULT_COMPACT_AT_PERCENT: u8 = 75;
pub const DEFAULT_KEEP_RECENT_TURNS: usize = 3;

const MIN_KEEP_EVENTS: usize = 8;
const MAX_ACTIONS: usize = 12;
const MAX_CHANGED_FILES: usize = 20;
const MAX_FAILURES: usize = 3;
const GOAL_CHARS: usize = 1_500;
const ASSISTANT_CHARS: usize = 1_000;
const FAILURE_CHARS: usize = 240;
const ACTION_CHARS: usize = 200;

#[derive(Debug, Clone)]
pub struct ContextConfig {
    /// Approximate model context window, in tokens.
    pub budget_tokens: usize,
    /// Compact when the estimate reaches this percentage of the budget.
    pub compact_at_percent: u8,
    /// Number of most recent user turns kept verbatim.
    pub keep_recent_turns: usize,
}

impl Default for ContextConfig {
    fn default() -> Self {
        Self {
            budget_tokens: DEFAULT_CONTEXT_BUDGET,
            compact_at_percent: DEFAULT_COMPACT_AT_PERCENT,
            keep_recent_turns: DEFAULT_KEEP_RECENT_TURNS,
        }
    }
}

impl ContextConfig {
    pub fn should_compact(&self, estimated_tokens: usize) -> bool {
        if self.budget_tokens == 0 {
            return false;
        }
        let percent = self.compact_at_percent.clamp(1, 100) as usize;
        let threshold = self.budget_tokens.saturating_mul(percent).div_ceil(100);
        estimated_tokens >= threshold
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Handoff {
    pub summary: String,
    /// Absolute event index replaced by this summary: `events[..upto]`.
    pub upto: usize,
}

/// Approximate tokens without a model-specific tokenizer.
///
/// ASCII text averages roughly four characters per token; non-ASCII characters
/// are counted one token each. This is conservative enough for a budget guard,
/// not a billing estimate.
pub fn estimate_text_tokens(text: &str) -> usize {
    let mut ascii = 0_usize;
    let mut other = 0_usize;
    for character in text.chars() {
        if character.is_ascii() {
            ascii += 1;
        } else {
            other += 1;
        }
    }
    ascii.div_ceil(4) + other
}

pub fn estimate_message_tokens(message: &ChatMessage) -> usize {
    let mut tokens = 4;
    if let Some(content) = &message.content {
        tokens += estimate_text_tokens(content);
    }
    if let Some(reasoning) = &message.reasoning_content {
        tokens += estimate_text_tokens(reasoning);
    }
    if let Some(calls) = &message.tool_calls {
        for call in calls {
            tokens += 4
                + estimate_text_tokens(&call.function.name)
                + estimate_text_tokens(&call.function.arguments);
        }
    }
    if let Some(call_id) = &message.tool_call_id {
        tokens += estimate_text_tokens(call_id);
    }
    tokens
}

pub fn estimate_tool_tokens(tool: &ToolSpec) -> usize {
    8 + estimate_text_tokens(&tool.function.name)
        + estimate_text_tokens(&tool.function.description)
        + estimate_text_tokens(&tool.function.parameters.to_string())
}

pub fn estimate_context(messages: &[ChatMessage], tools: &[ToolSpec]) -> usize {
    let message_tokens = messages.iter().map(estimate_message_tokens).sum::<usize>();
    let tool_tokens = tools.iter().map(estimate_tool_tokens).sum::<usize>();
    message_tokens + tool_tokens
}

/// Rebuild provider messages from durable session events.
///
/// The last `compaction` event applies to `events[..upto]`: its summary is
/// inserted at the cutoff, older compactions are ignored, and the compaction
/// event itself is never projected at its physical position.
pub fn project_history(events: &[Event]) -> Result<Vec<ChatMessage>> {
    let active_compaction = events
        .iter()
        .enumerate()
        .rev()
        .find(|(_, event)| matches!(event, Event::Compaction { .. }))
        .and_then(|(index, event)| match event {
            Event::Compaction { summary, upto, .. } => {
                let cutoff = usize::try_from(*upto).unwrap_or(usize::MAX);
                (!summary.is_empty() && cutoff <= index).then_some((cutoff, summary.as_str()))
            }
            _ => None,
        });

    let (cutoff, summary) = active_compaction.unwrap_or((0, ""));
    let mut messages = Vec::new();
    let mut pending_tools: Vec<String> = Vec::new();

    if !summary.is_empty() {
        messages.push(ChatMessage::system(summary.to_string()));
    }

    for (index, event) in events.iter().enumerate() {
        if index < cutoff {
            continue;
        }
        match event {
            Event::SessionStart { .. }
            | Event::TurnEnd { .. }
            | Event::Policy { .. }
            | Event::Approval { .. }
            | Event::Fork { .. }
            | Event::SubagentSpawn { .. }
            | Event::SubagentResult { .. }
            | Event::PlanMode { .. }
            | Event::Verification { .. }
            | Event::GoalSet { .. }
            | Event::GoalCleared { .. }
            | Event::GoalVerdict { .. }
            | Event::ModelChange { .. }
            | Event::PermissionChange { .. }
            | Event::ExtensionMount { .. }
            | Event::McpMount { .. }
            | Event::ExtensionUnmount { .. }
            | Event::ExtensionError { .. }
            | Event::Instructions { .. }
            | Event::Compaction { .. }
            | Event::InitProposal { .. }
            | Event::TaskSnapshot { .. }
            | Event::CheckSnapshot { .. }
            | Event::ToolEvidence { .. }
            | Event::InputSubmitted { .. }
            | Event::TaskStarted { .. }
            | Event::TaskFinished { .. }
            | Event::SessionEnd { .. } => {}
            Event::UserMessage { text, .. } | Event::InputApplied { text, .. } => {
                flush_pending_tools(&mut messages, &mut pending_tools);
                messages.push(ChatMessage::user(text.clone()));
            }
            Event::AssistantMessage {
                text,
                reasoning,
                tool_calls,
                ..
            } => {
                messages.push(ChatMessage::assistant(
                    non_empty(text.clone()),
                    reasoning.clone().filter(|value| !value.is_empty()),
                    tool_calls.clone(),
                ));
                pending_tools = tool_calls.iter().map(|call| call.id.clone()).collect();
            }
            Event::ToolResult {
                call_id, output, ..
            } => {
                pending_tools.retain(|pending| pending != call_id);
                messages.push(ChatMessage::tool(call_id.clone(), output.clone()));
            }
        }
    }

    flush_pending_tools(&mut messages, &mut pending_tools);

//! Layered `AGENTS.md` discovery.
//!
//! Instructions are discovered from the working directory up to the filesystem
//! root, nearest first. They are appended after the stable system prompt so the
//! prefix stays cache-friendly and changes only when a file changes.

use std::fs;
use std::path::Path;

const MAX_FILE_BYTES: usize = 32 * 1024;
const MAX_TOTAL_BYTES: usize = 64 * 1024;

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Instructions {
    /// Merged instruction text, empty when no `AGENTS.md` was found.
    pub text: String,
    /// Absolute paths that contributed text, nearest first.
    pub sources: Vec<String>,
    /// Stable FNV-1a digest of the merged text, used to explain cache changes.
    pub digest: String,
    /// Read or truncation problems worth surfacing.
    pub warnings: Vec<String>,
}

pub fn load(cwd: &Path) -> Instructions {
    let mut instructions = Instructions::default();
    let mut sections = Vec::new();
    let mut total_bytes = 0_usize;
    let mut omitted = false;

    for directory in cwd.ancestors() {
        let path = directory.join("AGENTS.md");
        if !path.is_file() {
            continue;
        }

        let bytes = match fs::read(&path) {
            Ok(bytes) => bytes,
            Err(error) => {
                instructions
                    .warnings
                    .push(format!("cannot read {}: {error}", path.display()));
                continue;
            }
        };
        if bytes.len() > MAX_FILE_BYTES {
            instructions.warnings.push(format!(
                "{} is larger than {MAX_FILE_BYTES} bytes; truncated",
                path.display()
            ));
        }
        let bytes = &bytes[..bytes.len().min(MAX_FILE_BYTES)];
        let content = String::from_utf8_lossy(bytes).trim().to_string();
        if content.is_empty() {
            continue;
        }

        let section = format!("### {}\n\n{content}\n\n", path.display());
        if total_bytes + section.len() > MAX_TOTAL_BYTES {
            omitted = true;
            break;
        }
        total_bytes += section.len();
        instructions.sources.push(path.display().to_string());
        sections.push(section);
    }

    if sections.is_empty() {
        return instructions;
    }

    let mut text = String::new();
    text.push_str("## Repository instructions\n\n");
    text.push_str(
        "The following AGENTS.md files apply to this workspace. Nearer files are listed first and take precedence when instructions conflict.\n\n",
    );
    for section in sections {
        text.push_str(&section);
    }
    if omitted {
        text.push_str(
            "_Additional AGENTS.md files were omitted because the instruction budget was exhausted._\n",
        );
    }

    instructions.digest = digest(&text);
    instructions.text = text;
    instructions
}

/// Compose the stable base prompt with discovered instructions.
pub fn compose_system_prompt(base: &str, instructions: &str) -> String {
    if instructions.is_empty() {
        base.to_string()
    } else {
        format!("{base}\n\n{instructions}")
    }
}

fn digest(text: &str) -> String {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for byte in text.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("{hash:016x}")
}

#[cfg(test)]
mod tests {
    use std::fs;
    use std::path::PathBuf;
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::time::{SystemTime, UNIX_EPOCH};

    use super::*;

    fn temp_dir(tag: &str) -> PathBuf {
        static COUNTER: AtomicU64 = AtomicU64::new(0);
        let sequence = COUNTER.fetch_add(1, Ordering::Relaxed);
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let directory =
            std::env::temp_dir().join(format!("niucode-instructions-{tag}-{stamp}-{sequence}"));
        let _ = fs::remove_dir_all(&directory);
        fs::create_dir_all(&directory).expect("create temp dir");
        directory
    }

    #[test]
    fn nearest_file_is_listed_first() {
        let root = temp_dir("layers");
        let child = root.join("crates/app");
        fs::create_dir_all(&child).expect("child");
        fs::write(root.join("AGENTS.md"), "root rule\n").expect("root rule");
        fs::write(child.join("AGENTS.md"), "child rule\n").expect("child rule");

        let loaded = load(&child);
        assert!(loaded.sources.len() >= 2);
        assert!(loaded.sources[0].ends_with("crates/app/AGENTS.md"));
        assert!(loaded.sources[1].ends_with("AGENTS.md"));
        let child_position = loaded.text.find("child rule").expect("child");
        let root_position = loaded.text.find("root rule").expect("root");
        assert!(child_position < root_position);
        assert_eq!(loaded.digest.len(), 16);

        fs::remove_dir_all(root).expect("cleanup");
    }

    #[test]
    fn modifying_a_file_changes_the_digest() {
        let directory = temp_dir("change");
        let path = directory.join("AGENTS.md");
        fs::write(&path, "first\n").expect("write");
        let first = load(&directory);
        fs::write(&path, "second\n").expect("rewrite");
        let second = load(&directory);
        assert_eq!(first.sources, second.sources);
        assert_ne!(first.digest, second.digest);
        assert!(second.text.contains("second"));

        fs::remove_dir_all(directory).expect("cleanup");
    }

    #[test]
    fn empty_files_are_not_sources() {
        let directory = temp_dir("empty");
        let path = directory.join("AGENTS.md");
        assert!(!load(&directory)
            .sources
            .contains(&path.display().to_string()));
        fs::write(&path, "  \n").expect("write");
        let loaded = load(&directory);
        assert!(!loaded.sources.contains(&path.display().to_string()));

        fs::remove_dir_all(directory).expect("cleanup");
    }
}

