pub struct AuthStore {
    file: FileStore,
    keyring_enabled: bool,
}

impl AuthStore {
    pub fn new() -> Result<Self, AuthError> {
        let directory = config_dir()?;
        let keyring_enabled =
            !matches!(env::var("NIUCODE_AUTH_DISABLE_KEYRING").as_deref(), Ok("1"));

        Ok(Self {
            file: FileStore::new(directory.join("credentials.toml")),
            keyring_enabled,
        })
    }

    /// Test/local helper: use a specific config directory and skip the keyring.
    pub fn at(directory: &Path) -> Self {
        Self {
            file: FileStore::new(directory.join("credentials.toml")),
            keyring_enabled: false,
        }
    }

    pub fn credentials_path(&self) -> &Path {
        self.file.path()
    }

    pub fn resolve(&self, provider: &str) -> Result<Option<Resolved>, AuthError> {
        let env_value = env_var(provider).and_then(|name| env::var(name).ok());
        self.resolve_with(provider, env_value)
    }

    /// Explicit launch-time import. Inherited environment wins; the file is never executed.
    /// The imported literal acts as an environment value, before keyring/file fallback.
    pub fn resolve_with_shell_file(
        &self,
        provider: &str,
        path: &Path,
    ) -> Result<Option<Resolved>, AuthError> {
        let value = match env_var(provider) {
            Some(name) => match env::var(name).ok().filter(|value| !value.trim().is_empty()) {
                Some(value) => Some(value),
                None => shell::literal_assignment(path, name)?,
            },
            None => None,
        };
        self.resolve_with(provider, value)
    }

    pub fn resolve_with(
        &self,
        provider: &str,
        env_value: Option<String>,
    ) -> Result<Option<Resolved>, AuthError> {
        if let Some(value) = env_value
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
        {
            return Ok(Some(Resolved {
                key: SecretKey(value),
                source: Source::Env,
            }));
        }

        if self.keyring_enabled {
            if let Some(value) = keyring_store::get(provider) {
                return Ok(Some(Resolved {
                    key: SecretKey(value),
                    source: Source::Keyring,
                }));
            }
        }

        if let Some(value) = self.file.get(provider)? {
            return Ok(Some(Resolved {
                key: SecretKey(value),
                source: Source::File,
            }));
        }

        Ok(None)
    }

    pub fn status(&self, provider: &str) -> Result<AuthStatus, AuthError> {
        let env_value = env_var(provider).and_then(|name| env::var(name).ok());
        self.status_with(provider, env_value)
    }

    pub fn status_with(
        &self,
        provider: &str,
        env_value: Option<String>,
    ) -> Result<AuthStatus, AuthError> {
        let env = env_value
            .as_deref()
            .map(|value| !value.trim().is_empty())
            .unwrap_or(false);
        let keyring = if self.keyring_enabled {
