use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::AuthError;

#[derive(Debug, Default, Serialize, Deserialize)]
struct Credentials {
    #[serde(default)]
    providers: BTreeMap<String, ProviderEntry>,
}

#[derive(Debug, Serialize, Deserialize)]
struct ProviderEntry {
    api_key: String,
}

pub(crate) struct FileStore {
    path: PathBuf,
}

impl FileStore {
    pub(crate) fn new(path: PathBuf) -> Self {
        Self { path }
    }

    pub(crate) fn path(&self) -> &Path {
        &self.path
    }

    pub(crate) fn get(&self, provider: &str) -> Result<Option<String>, AuthError> {
        let credentials = self.read()?;
        Ok(credentials
            .providers
            .get(provider)
            .map(|entry| entry.api_key.trim().to_string())
            .filter(|key| !key.is_empty()))
    }

    pub(crate) fn set(&self, provider: &str, api_key: &str) -> Result<(), AuthError> {
        let mut credentials = self.read()?;
        credentials.providers.insert(
            provider.to_string(),
            ProviderEntry {
                api_key: api_key.to_string(),
            },
        );
        self.write(&credentials)
    }

    pub(crate) fn remove(&self, provider: &str) -> Result<bool, AuthError> {
        let mut credentials = self.read()?;
        let removed = credentials.providers.remove(provider).is_some();
        if removed {
            self.write(&credentials)?;
        }
        Ok(removed)
    }

    pub(crate) fn is_private(&self) -> bool {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            self.path
                .metadata()
                .map(|metadata| metadata.permissions().mode() & 0o077 == 0)
                .unwrap_or(true)
        }
        #[cfg(not(unix))]
        {
            true
        }
    }

    fn read(&self) -> Result<Credentials, AuthError> {
        if !self.path.exists() {
            return Ok(Credentials::default());
        }

        let raw = fs::read_to_string(&self.path)?;
        if raw.trim().is_empty() {
            return Ok(Credentials::default());
        }

        toml::from_str(&raw).map_err(|_| AuthError::CorruptCredentials)
    }

    fn write(&self, credentials: &Credentials) -> Result<(), AuthError> {
        let parent = self.path.parent().ok_or(AuthError::NoConfigDir)?;
        let existed = parent.exists();
        fs::create_dir_all(parent)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            if !existed {
                fs::set_permissions(parent, fs::Permissions::from_mode(0o700))?;
            }
        }

        let data = toml::to_string_pretty(credentials).map_err(|_| AuthError::Serialize)?;
        let temporary = self.path.with_extension("toml.tmp");
        fs::write(&temporary, data)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&temporary, fs::Permissions::from_mode(0o600))?;
        }

        fs::rename(&temporary, &self.path)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&self.path, fs::Permissions::from_mode(0o600))?;
        }

        Ok(())
    }
}

use keyring::Entry;

const SERVICE: &str = "niucode";

pub(crate) fn get(provider: &str) -> Option<String> {
    let entry = Entry::new(SERVICE, provider).ok()?;
    entry
        .get_password()
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

pub(crate) fn set(provider: &str, api_key: &str) -> bool {
    Entry::new(SERVICE, provider)
        .and_then(|entry| entry.set_password(api_key))
        .is_ok()
}

pub(crate) fn delete(provider: &str) -> bool {
    Entry::new(SERVICE, provider)
        .and_then(|entry| entry.delete_credential())
        .is_ok()
}

//! Explicit import of a literal shell assignment, without executing shell code.
use crate::AuthError;
use std::path::Path;

pub(crate) fn literal_assignment(path: &Path, name: &str) -> Result<Option<String>, AuthError> {
    let text = std::fs::read_to_string(path)?;
    let mut value = None;
    for line in text.lines() {
        let line = line.trim();
        let line = line.strip_prefix("export ").unwrap_or(line).trim();
        let Some((key, raw)) = line.split_once('=') else {
            continue;
        };
        if key.trim() != name {
            continue;
        }
        let raw = raw.trim();
        let parsed = if let Some(first) = raw.chars().next().filter(|c| *c == '\'' || *c == '"') {
            let tail = &raw[1..];
            let end = tail
                .find(first)
                .ok_or(AuthError::UnsupportedShellAssignment)?;
            let after = tail[end + 1..].trim();
            if !after.is_empty() && !after.starts_with('#') {
                return Err(AuthError::UnsupportedShellAssignment);
            }
            &tail[..end]
        } else {
            let token = raw.split_whitespace().next().unwrap_or("");
            let after = raw[token.len()..].trim();
            if !after.is_empty() && !after.starts_with('#') {
                return Err(AuthError::UnsupportedShellAssignment);
            }
            token
        };
        // API keys need none of shell's expansion/escape operators.
        if parsed.is_empty()
            || !parsed
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b"-_./:+=".contains(&b))
        {
            return Err(AuthError::UnsupportedShellAssignment);
        }
        value = Some(parsed.to_owned());
    }
    Ok(value)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn imports_only_literals_and_never_expands_shell() {
        let path = std::env::temp_dir().join(format!("niucode-auth-shell-{}", std::process::id()));
        std::fs::write(
            &path,
            "echo unrelated\nexport DEEPSEEK_API_KEY='test-key' # comment\n",
        )
        .unwrap();
        assert_eq!(
            literal_assignment(&path, "DEEPSEEK_API_KEY").unwrap(),
            Some("test-key".into())
        );
        std::fs::write(
            &path,
            "export DEEPSEEK_API_KEY=\"$(touch /tmp/not-executed)\"\n",
        )
        .unwrap();
        assert!(literal_assignment(&path, "DEEPSEEK_API_KEY").is_err());
        std::fs::write(&path, "export DEEPSEEK_API_KEY=key unexpected\n").unwrap();
        assert!(literal_assignment(&path, "DEEPSEEK_API_KEY").is_err());
        std::fs::write(&path, "export DEEPSEEK_API_KEY='key'; echo surprise\n").unwrap();
        assert!(literal_assignment(&path, "DEEPSEEK_API_KEY").is_err());
        std::fs::remove_file(path).unwrap();
    }
}

//! Sidecar extension host.
//!
//! A plugin is a local process speaking line-delimited JSON-RPC over stdio.
//! Tools are discovered during `initialize`; calls are serialized per plugin
//! for now (the manifest does not yet declare a concurrency model).

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::process::Stdio;
