/// Namespaced name exposed to the agent. Server/tool characters outside the
/// conservative set are replaced so the result is always a valid tool name.
pub fn exposed_name(server: &str, tool: &str) -> String {
    format!("mcp__{}__{}", sanitize(server), sanitize(tool))
}

fn sanitize(value: &str) -> String {
    let mut out = String::new();
    for character in value.chars() {
        if character.is_ascii_alphanumeric() || character == '_' || character == '-' {
            out.push(character);
        } else {
            out.push('_');
        }
    }
    if out.is_empty() {
        "unnamed".to_string()
    } else {
        out
    }
}

pub struct McpClient {
    server: String,
    child: Child,
    stdin: ChildStdin,
    stdout: BufReader<ChildStdout>,
    next_id: u64,
}

impl McpClient {
    pub async fn connect(spec: &McpServerSpec, limit: Duration) -> Result<Self> {
        Self::connect_with(spec, limit, false).await
    }

    async fn connect_with(
        spec: &McpServerSpec,
        limit: Duration,
        allow_write: bool,
    ) -> Result<Self> {
        spec.validate_policy(allow_write)?;
        let mut command = Command::new(&spec.command);
        command
            .args(&spec.args)
            .env_clear()
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null());
        for (key, value) in &spec.env {
            command.env(key, value);
        }
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            command.as_std_mut().process_group(0);
        }
        let mut child = command
            .spawn()
            .with_context(|| format!("spawn MCP server {}", spec.name))?;

//! Global per-project workspace layout.
//!
//! niucode intentionally does not create a `.niucode` directory in the project
//! root. All state lives under `~/.niucode/projects/<key>/`.

use std::fs;
use std::path::{Path, PathBuf};

